          theme == other.theme &&
          language == other.language &&
          refreshIntervalMin == other.refreshIntervalMin &&
          reading == other.reading;
}

/// The kind of source a feed represents.
enum SourceType {
  rss,
  youtube,
  podcast,
  mastodon,
  bluesky,
  reddit,
  newsletter,
  ;
}

/// Supported formats for an AI-generated article summary.
enum SummaryTemplate {
  classic,
  news5W1H,
  decision,
  funnel,
  argument,
  minimal,
  ;
}

/// A lightweight tag representation.
class Tag {
  final PlatformInt64 id;
  final String name;
  final String color;

  const Tag({
    required this.id,
    required this.name,
    required this.color,
  });

  @override
  int get hashCode => id.hashCode ^ name.hashCode ^ color.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Tag &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          color == other.color;
}

/// A tag exposed for read-only article filtering.
class TagSummary {
  final PlatformInt64 id;
  final String name;
  final String color;
  final PlatformInt64 articleCount;
  final PlatformInt64 position;

  const TagSummary({
    required this.id,
    required this.name,
    required this.color,
    required this.articleCount,
    required this.position,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      name.hashCode ^
      color.hashCode ^
      articleCount.hashCode ^
      position.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TagSummary &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          color == other.color &&
          articleCount == other.articleCount &&
          position == other.position;
}
